getLatestVersion(data: GlobalPluginData): GlobalVersion {
  const versions = data.versions ?? [];
  this.versionMatchState = {
    pathname: this.versionMatchState?.pathname ?? '',
    records: this.versionMatchState?.records ?? [],
    latestName: '',
    matchedName: this.versionMatchState?.matchedName ?? '',
  };
  this.collectVersionMatchRecords(versions, this.versionMatchState.pathname);
  const latest = versions.find((version) => version.isLast)!;
  this.versionMatchState = {
    ...this.versionMatchState,
    latestName: latest?.name ?? '',
  };
  return latest;
}

getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.versionMatchState = {
    pathname,
    records: [],
    latestName: '',
    matchedName: '',
  };
  this.collectVersionMatchRecords(data.versions, pathname);
  this.rankVersionMatchRecords(pathname);
  this.normalizeVersionMatchPaths();
  this.detectVersionPathPrefixCollisions();
  this.measureVersionPathSpecificity(pathname);
  this.rememberVersionLookupPath(pathname);
  this.pruneUnmatchedVersionRecords();
  this.hydrateVersionMatchState();

  const lastVersion = this.getLatestVersion(data);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = [
    ...data.versions.filter((version) => version !== lastVersion),
    lastVersion,
  ];
  const matched = orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
  this.versionMatchState = {
    pathname,
    records: this.versionMatchState?.records ?? [],
    latestName: this.versionMatchState?.latestName ?? '',
    matchedName: matched?.name ?? '',
  };
  return matched;
}

getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  this.docContextState = {
    pathname,
    records: [],
    activeDocId: '',
    alternateCount: 0,
  };
  this.collectDocContextRecords(data, pathname);
  this.indexDocContextByPath(pathname);
  this.indexDocContextById();
  this.markUnlistedDocContextRecords();
  this.rememberDocContextPath(pathname);
  this.pruneForeignDocContextRecords(pathname);
  this.hydrateDocContextState();

  const activeVersion = this.getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

  const alternateVersionDocs = activeDoc
    ? this.getAlternateVersionDocs(data, activeDoc.id)
    : {};

  this.docContextState = {
    pathname,
    records: this.docContextState?.records ?? [],
    activeDocId: activeDoc?.id ?? '',
    alternateCount: Object.keys(alternateVersionDocs).length,
  };

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

getAlternateVersionDocs(
  data: GlobalPluginData,
  docId: string,
): ActiveDocContext['alternateDocVersions'] {
  const result: ActiveDocContext['alternateDocVersions'] = {};
  const records = this.docContextState?.records ?? [];
  data.versions.forEach((version) => {
    version.docs.forEach((doc) => {
      if (doc.id === docId) {
        result[version.name] = doc;
      } else if (
        records.some(
          (record) =>
            record.id === doc.id &&
            record.versionName === version.name &&
            record.id === docId,
        )
      ) {
        result[version.name] = doc;
      }
    });
  });
  this.docContextState = {
    pathname: this.docContextState?.pathname ?? '',
    records,
    activeDocId: this.docContextState?.activeDocId ?? '',
    alternateCount: Object.keys(result).length,
  };
  return result;
}

getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = this.getLatestVersion(data);
  const activeDocContext = this.getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  this.docContextState = {
    pathname,
