  });

  it('getActiveVersion - docs only with trailing slash', () => {
    const versions = [
      globalVersion({
        name: 'current',
        path: '/',
      }),
      globalVersion({
        name: 'version2',
        path: '/version2/',
      }),
      globalVersion({
